#!/usr/bin/env node

import fs from 'fs'

// Read command line arguments
const args = process.argv.slice(2)

if (args.length !== 1 || !['json', 'keys'].includes(args[0])) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}

const mode = args[0]

// Read stdin
const input = fs.readFileSync(0, 'utf-8')

try {
  const parser = new TOMLParser(input)
  const data = parser.parse()

  if (mode === 'json') {
    const json = JSON.stringify(data, Object.keys(data).sort(), 2)
    process.stdout.write(json + '\n')
  } else {
    // keys mode
    const lines = []
    printKeys(data, '', lines)
    lines.forEach(line => process.stdout.write(line + '\n'))
  }

  process.exit(0)
} catch (error) {
  process.stderr.write(error.message + '\n')
  process.exit(2)
}

function printKeys(obj, path, lines) {
  const keys = Object.keys(obj).sort()
  for (const key of keys) {
    const fullPath = path ? path + '.' + key : key
    const value = obj[key]
    const type = getType(value)
    lines.push(`${fullPath} ${type}`)
    if (type === 'table') {
      printKeys(value, fullPath, lines)
    } else if (type === 'array' && Array.isArray(value) && value.length > 0 && typeof value[0] === 'object') {
      // Array of tables
      for (let i = 0; i < value.length; i++) {
        const indexPath = `${fullPath}[${i}]`
        printKeys(value[i], indexPath, lines)
      }
    }
  }
}

function getType(value) {
  if (Array.isArray(value)) {
    if (value.length > 0 && typeof value[0] === 'object' && !Array.isArray(value[0])) {
      return 'array'
    }
    return 'array'
  }
  if (typeof value === 'object' && value !== null) {
    return 'table'
  }
  if (typeof value === 'boolean') {
    return 'boolean'
  }
  if (typeof value === 'string') {
    return 'string'
  }
  if (Number.isInteger(value)) {
    return 'integer'
  }
  return 'float'
}

class TOMLParser {
  constructor(input) {
    this.input = input
    this.lines = input.split('\n')
    if (this.lines.length > 0 && this.lines[this.lines.length - 1] === '') {
      this.lines.pop()
    }
    this.root = {}
    this.current = this.root
    this.path = []
    this.lineNum = 0
  }

  parse() {
    for (this.lineNum = 0; this.lineNum < this.lines.length; this.lineNum++) {
      const line = this.lines[this.lineNum]
      this.parseLine(line)
    }
    return this.root
  }

  parseLine(line) {
    // Remove comments
    const trimmedLine = this.stripComments(line)

    // Check if it's an empty line
    if (trimmedLine.match(/^\s*$/)) {
      return
    }

    // Check if it's a header
    if (trimmedLine.match(/^\s*\[\[/)) {
      this.parseArrayHeader(trimmedLine)
    } else if (trimmedLine.match(/^\s*\[/)) {
      this.parseTableHeader(trimmedLine)
    } else {
      this.parseKeyValue(trimmedLine)
    }
  }

  stripComments(line) {
    let inBasicString = false
    let inLiteralString = false
    let inArray = 0
    let inInlineTable = 0

    for (let i = 0; i < line.length; i++) {
      const char = line[i]
      const prev = i > 0 ? line[i - 1] : ''

      if (inBasicString) {
        if (char === '"' && prev !== '\\') {
          inBasicString = false
        }
      } else if (inLiteralString) {
        if (char === "'") {
          inLiteralString = false
        }
      } else {
        if (char === '"') {
          inBasicString = true
        } else if (char === "'") {
          inLiteralString = true
        } else if (char === '[') {
          inArray++
        } else if (char === ']') {
          inArray--
        } else if (char === '{') {
          inInlineTable++
        } else if (char === '}') {
          inInlineTable--
        } else if ((char === '#' || char === ';') && inArray === 0 && inInlineTable === 0) {
          return line.substring(0, i).trimEnd()
        }
      }
    }

    return line.trimEnd()
  }

  parseTableHeader(line) {
    const match = line.match(/^\s*\[\s*(.+?)\s*\]\s*$/)
    if (!match) {
      throw new Error(`error: line ${this.lineNum + 1}: unterminated table header`)
    }

    const names = this.parseDottedName(match[1])
    this.setCurrentTable(names, false)
  }

  parseArrayHeader(line) {
    const match = line.match(/^\s*\[\[\s*(.+?)\s*\]\]\s*$/)
    if (!match) {
      throw new Error(`error: line ${this.lineNum + 1}: unterminated table header`)
    }

    const names = this.parseDottedName(match[1])
    this.setCurrentTable(names, true)
  }

  parseKeyValue(line) {
    const eqIdx = line.indexOf('=')
    if (eqIdx === -1) {
      throw new Error(`error: line ${this.lineNum + 1}: expected key = value`)
    }

    const keyPart = line.substring(0, eqIdx).trim()
    const valuePart = line.substring(eqIdx + 1).trim()

    if (!keyPart) {
      throw new Error(`error: line ${this.lineNum + 1}: expected a name`)
    }

    const names = this.parseDottedName(keyPart)
    const value = this.parseValue(valuePart)

    // Set value in current table
    let target = this.current
    for (let i = 0; i < names.length - 1; i++) {
      const name = names[i]
      if (!(name in target)) {
        target[name] = {}
      } else if (typeof target[name] !== 'object' || Array.isArray(target[name])) {
        throw new Error(`error: line ${this.lineNum + 1}: ${this.pathToString([...this.path, ...names.slice(0, i + 1)])} is not a table`)
      }
      target = target[name]
    }

    const finalKey = names[names.length - 1]
    if (finalKey in target) {
      throw new Error(`error: line ${this.lineNum + 1}: key ${this.pathToString([...this.path, ...names])} is defined twice`)
    }

    target[finalKey] = value
  }

  parseDottedName(text) {
    const parts = []
    let current = ''
    let i = 0

    while (i < text.length) {
      const char = text[i]

      if (char === ' ' || char === '\t') {
        i++
      } else if (char === '"' || char === "'") {
        const quote = char
        let str = ''
        i++
        while (i < text.length) {
          if (text[i] === quote) {
            i++
            current += str
            break
          }
          if (text[i] === '\\' && quote === '"') {
            i++
            if (i < text.length) {
              str += text[i]
              i++
            }
          } else {
            str += text[i]
            i++
          }
        }
      } else if (char === '.') {
        if (!current) {
          throw new Error(`error: line ${this.lineNum + 1}: expected a name`)
        }
        parts.push(current)
        current = ''
        i++
      } else if (/[A-Za-z0-9_-]/.test(char)) {
        current += char
        i++
      } else {
        throw new Error(`error: line ${this.lineNum + 1}: expected a name`)
      }
    }

    if (current) {
      parts.push(current)
    } else if (parts.length === 0) {
      throw new Error(`error: line ${this.lineNum + 1}: expected a name`)
    }

    return parts
  }

  parseValue(text) {
    let pos = 0

    const skipWhitespace = () => {
      while (pos < text.length && (text[pos] === ' ' || text[pos] === '\t')) {
        pos++
      }
    }

    skipWhitespace()

    if (pos >= text.length) {
      throw new Error(`error: line ${this.lineNum + 1}: expected a value`)
    }

    const char = text[pos]

    if (char === '"') {
      const result = this.parseBasicString(text, pos)
      pos = result.pos
      skipWhitespace()
      if (pos < text.length && text[pos] !== '#' && text[pos] !== ';') {
        throw new Error(`error: line ${this.lineNum + 1}: trailing text after a value`)
      }
      return result.value
    }

    if (char === "'") {
      const result = this.parseLiteralString(text, pos)
      pos = result.pos
      skipWhitespace()
      if (pos < text.length && text[pos] !== '#' && text[pos] !== ';') {
        throw new Error(`error: line ${this.lineNum + 1}: trailing text after a value`)
      }
      return result.value
    }

    if (char === '[') {
      const result = this.parseArray(text, pos)
      pos = result.pos
      skipWhitespace()
      if (pos < text.length && text[pos] !== '#' && text[pos] !== ';') {
        throw new Error(`error: line ${this.lineNum + 1}: trailing text after a value`)
      }
      return result.value
    }

    if (char === '{') {
      const result = this.parseInlineTable(text, pos)
      pos = result.pos
      skipWhitespace()
      if (pos < text.length && text[pos] !== '#' && text[pos] !== ';') {
        throw new Error(`error: line ${this.lineNum + 1}: trailing text after a value`)
      }
      return result.value
    }

    // Parse bare word (true, false, number, etc)
    let bareWord = ''
    while (pos < text.length && text[pos] !== ' ' && text[pos] !== '\t' && text[pos] !== '#' && text[pos] !== ';' && text[pos] !== ',') {
      bareWord += text[pos]
      pos++
    }

    if (bareWord === 'true') {
      skipWhitespace()
      if (pos < text.length && text[pos] !== '#' && text[pos] !== ';') {
        throw new Error(`error: line ${this.lineNum + 1}: trailing text after a value`)
      }
      return true
    }

    if (bareWord === 'false') {
      skipWhitespace()
      if (pos < text.length && text[pos] !== '#' && text[pos] !== ';') {
        throw new Error(`error: line ${this.lineNum + 1}: trailing text after a value`)
      }
      return false
    }

    // Try to parse as number
    if (/^[+-]?[0-9_]+(\.[0-9_]+)?([eE][+-]?[0-9_]+)?$/.test(bareWord)) {
      const num = this.parseNumber(bareWord)
      if (num !== null) {
        skipWhitespace()
        if (pos < text.length && text[pos] !== '#' && text[pos] !== ';') {
          throw new Error(`error: line ${this.lineNum + 1}: trailing text after a value`)
        }
        return num
      }
    }

    throw new Error(`error: line ${this.lineNum + 1}: invalid value ${bareWord}`)
  }

  parseNumber(str) {
    // Remove underscores
    const cleaned = str.replace(/_/g, '')

    // Check if it's a float
    if (cleaned.includes('.') || cleaned.includes('e') || cleaned.includes('E')) {
      return parseFloat(cleaned)
    }

    // It's an integer
    return parseInt(cleaned, 10)
  }

  parseBasicString(text, startPos) {
    let pos = startPos + 1
    let result = ''

    while (pos < text.length) {
      const char = text[pos]

      if (char === '"') {
        return { value: result, pos: pos + 1 }
      }

      if (char === '\\') {
        if (pos + 1 >= text.length) {
          throw new Error(`error: line ${this.lineNum + 1}: unterminated string`)
        }

        const nextChar = text[pos + 1]
        switch (nextChar) {
          case '"':
            result += '"'
            pos += 2
            break
          case '\\':
            result += '\\'
            pos += 2
            break
          case 'n':
            result += '\n'
            pos += 2
            break
          case 't':
            result += '\t'
            pos += 2
            break
          case 'r':
            result += '\r'
            pos += 2
            break
          case '0':
            result += '\0'
            pos += 2
            break
          case 'u':
            if (pos + 5 >= text.length) {
              throw new Error(`error: line ${this.lineNum + 1}: invalid escape \\${nextChar}`)
            }
            const hex = text.substring(pos + 2, pos + 6)
            if (!/^[0-9a-fA-F]{4}$/.test(hex)) {
              throw new Error(`error: line ${this.lineNum + 1}: invalid escape \\${nextChar}`)
            }
            result += String.fromCharCode(parseInt(hex, 16))
            pos += 6
            break
          default:
            throw new Error(`error: line ${this.lineNum + 1}: invalid escape \\${nextChar}`)
        }
      } else {
        result += char
        pos++
      }
    }

    throw new Error(`error: line ${this.lineNum + 1}: unterminated string`)
  }

  parseLiteralString(text, startPos) {
    let pos = startPos + 1
    let result = ''

    while (pos < text.length) {
      const char = text[pos]

      if (char === "'") {
        return { value: result, pos: pos + 1 }
      }

      result += char
      pos++
    }

    throw new Error(`error: line ${this.lineNum + 1}: unterminated string`)
  }

  parseArray(text, startPos) {
    let pos = startPos + 1
    const items = []

    const skipWhitespace = () => {
      while (pos < text.length && (text[pos] === ' ' || text[pos] === '\t' || text[pos] === '\n')) {
        pos++
      }
    }

    skipWhitespace()

    while (pos < text.length && text[pos] !== ']') {
      if (text[pos] === ',') {
        pos++
        skipWhitespace()
        continue
      }

      const result = this.parseArrayValue(text, pos)
      items.push(result.value)
      pos = result.pos

      skipWhitespace()

      if (pos < text.length && text[pos] === ',') {
        pos++
        skipWhitespace()
      }
    }

    if (pos >= text.length) {
      throw new Error(`error: line ${this.lineNum + 1}: unterminated array`)
    }

    return { value: items, pos: pos + 1 }
  }

  parseArrayValue(text, startPos) {
    let pos = startPos

    const skipWhitespace = () => {
      while (pos < text.length && (text[pos] === ' ' || text[pos] === '\t' || text[pos] === '\n')) {
        pos++
      }
    }

    skipWhitespace()

    if (pos >= text.length) {
      throw new Error(`error: line ${this.lineNum + 1}: expected a value`)
    }

    const char = text[pos]

    if (char === '"') {
      return this.parseBasicString(text, pos)
    }

    if (char === "'") {
      return this.parseLiteralString(text, pos)
    }

    if (char === '[') {
      return this.parseArray(text, pos)
    }

    if (char === '{') {
      return this.parseInlineTable(text, pos)
    }

    // Parse bare word
    let bareWord = ''
    while (pos < text.length && text[pos] !== ' ' && text[pos] !== '\t' && text[pos] !== ',' && text[pos] !== ']' && text[pos] !== '}') {
      bareWord += text[pos]
      pos++
    }

    if (bareWord === 'true') {
      return { value: true, pos }
    }

    if (bareWord === 'false') {
      return { value: false, pos }
    }

    if (/^[+-]?[0-9_]+(\.[0-9_]+)?([eE][+-]?[0-9_]+)?$/.test(bareWord)) {
      const num = this.parseNumber(bareWord)
      if (num !== null) {
        return { value: num, pos }
      }
    }

    throw new Error(`error: line ${this.lineNum + 1}: invalid value ${bareWord}`)
  }

  parseInlineTable(text, startPos) {
    let pos = startPos + 1
    const table = {}

    const skipWhitespace = () => {
      while (pos < text.length && (text[pos] === ' ' || text[pos] === '\t')) {
        pos++
      }
    }

    skipWhitespace()

    while (pos < text.length && text[pos] !== '}') {
      skipWhitespace()

      if (pos >= text.length || text[pos] === '}') {
        break
      }

      // Parse key
      const keyResult = this.parseInlineTableKey(text, pos)
      const keys = keyResult.keys
      pos = keyResult.pos

      skipWhitespace()

      if (pos >= text.length || text[pos] !== '=') {
        throw new Error(`error: line ${this.lineNum + 1}: expected = in an inline table`)
      }

      pos++
      skipWhitespace()

      // Parse value
      const valueResult = this.parseArrayValue(text, pos)
      pos = valueResult.pos

      // Set value in table
      let target = table
      for (let i = 0; i < keys.length - 1; i++) {
        const key = keys[i]
        if (!(key in target)) {
          target[key] = {}
        }
        target = target[key]
      }

      const finalKey = keys[keys.length - 1]
      if (finalKey in target) {
        throw new Error(`error: line ${this.lineNum + 1}: key ${finalKey} is defined twice`)
      }
      target[finalKey] = valueResult.value

      skipWhitespace()

      if (pos < text.length && text[pos] === ',') {
        pos++
      }
    }

    if (pos >= text.length) {
      throw new Error(`error: line ${this.lineNum + 1}: unterminated inline table`)
    }

    return { value: table, pos: pos + 1 }
  }

  parseInlineTableKey(text, startPos) {
    let pos = startPos

    const skipWhitespace = () => {
      while (pos < text.length && (text[pos] === ' ' || text[pos] === '\t')) {
        pos++
      }
    }

    const parts = []
    let current = ''

    while (pos < text.length) {
      const char = text[pos]

      if (char === ' ' || char === '\t') {
        if (current) {
          parts.push(current)
          current = ''
        }
        skipWhitespace()
      } else if (char === '"' || char === "'") {
        const quote = char
        let str = ''
        pos++
        while (pos < text.length) {
          if (text[pos] === quote) {
            pos++
            current += str
            break
          }
          if (text[pos] === '\\' && quote === '"') {
            pos++
            if (pos < text.length) {
              str += text[pos]
              pos++
            }
