{"file_path":"./src/parse.js","content":"/**
 * The configuration parser. One line is one directive, so the whole grammar is
 * a recursive descent over a single line of text.
 */

import { ParseError, joinKey, joinIndex } from './errors.js'
import {
  newTable,
  newArrayTable,
  newArray,
  newString,
  newInteger,
  newFloat,
  newBoolean
} from './values.js'

const BARE = /[A-Za-z0-9_-]/
const INTEGER = /^[+-]?\d+(?:_\d+)*$/
const FLOAT = /^[+-]?\d+(?:_\d+)*(?:\.\d+(?:_\d+)*)?(?:[eE][+-]?\d+(?:_\d+)*)?$/
const HEX4 = /^[0-9a-fA-F]{4}$/

class LineParser {
  constructor(text, line) {
    this.s = text
    this.n = text.length
    this.i = 0
    this.line = line
  }

  fail(reason) {
    throw new ParseError(this.line, reason)
  }

  /** Spaces and tabs are the only whitespace a line carries. */
  skipSpace() {
    while (this.i < this.n && (this.s[this.i] === ' ' || this.s[this.i] === '\t')) this.i++
  }

  peek() {
    return this.i < this.n ? this.s[this.i] : ''
  }

  /** True where the text runs out or a comment takes the rest of the line. */
  atEnd() {
    if (this.i >= this.n) return true
    const c = this.s[this.i]
    return c === '#' || c === ';'
  }

  basicString() {
    this.i++
    let out = ''
    for (;;) {
      if (this.i >= this.n) this.fail('unterminated string')
      const c = this.s[this.i]
      if (c === '"') {
        this.i++
        return out
      }
      if (c !== '\\') {
        out += c
        this.i++
        continue
      }
      if (this.i + 1 >= this.n) this.fail('unterminated string')
      const e = this.s[this.i + 1]
      if (e === '"' || e === '\\') {
        out += e
        this.i += 2
      } else if (e === 'n') {
        out += '\n'
        this.i += 2
      } else if (e === 't') {
        out += '\t'
        this.i += 2
      } else if (e === 'r') {
        out += '\r'
        this.i += 2
      } else if (e === '0') {
        out += '\0'
        this.i += 2
      } else if (e === 'u') {
        const hex = this.s.slice(this.i + 2, this.i + 6)
        if (!HEX4.test(hex)) this.fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(hex, 16))
        this.i += 6
      } else {
        this.fail(`invalid escape \\${e}`)
      }
    }
  }

  literalString() {
    this.i++
    let out = ''
    for (;;) {
      if (this.i >= this.n) this.fail('unterminated string')
      const c = this.s[this.i]
      if (c === "'") {
        this.i++
        return out
      }
      out += c
      this.i++
    }
  }

  name() {
    const c = this.peek()
    if (c === '"') return this.basicString()
    if (c === "'") return this.literalString()
    const start = this.i
    while (this.i < this.n && BARE.test(this.s[this.i])) this.i++
    if (this.i === start) this.fail('expected a name')
    return this.s.slice(start, this.i)
  }

  /** Names joined by dots, with spaces and tabs allowed around each dot. */
  dottedName() {
    const parts = []
    this.skipSpace()
    parts.push(this.name())
    for (;;) {
      const mark = this.i
      this.skipSpace()
      if (this.peek() === '.') {
        this.i++
        this.skipSpace()
        parts.push(this.name())
      } else {
        this.i = mark
        return parts
      }
    }
  }

  value(path) {
    this.skipSpace()
    const c = this.peek()
    if (this.atEnd() || c === ',' || c === ']' || c === '}') this.fail('expected a value')
    if (c === '"') return newString(this.basicString())
    if (c === "'") return newString(this.literalString())
    if (c === '[') return this.array(path)
    if (c === '{') return this.inlineTable(path)
    const start = this.i
    while (this.i < this.n && !' \t,]}'.includes(this.s[this.i])) this.i++
    const word = this.s.slice(start, this.i)
    if (word === 'true') return newBoolean(true)
    if (word === 'false') return newBoolean(false)
    if (INTEGER.test(word)) return newInteger(Number(word.replace(/_/g, '')))
    if (FLOAT.test(word)) return newFloat(Number(word.replace(/_/g, '')))
    this.fail(`invalid value ${word}`)
  }

  array(path) {
    this.i++
    const items = []
    for (;;) {
      this.skipSpace()
      if (this.atEnd()) this.fail('unterminated array')
      if (this.peek() === ']') {
        this.i++
        return newArray(items)
      }
      items.push(this.value(joinIndex(path, items.length)))
      this.skipSpace()
      if (this.atEnd()) this.fail('unterminated array')
      const c = this.peek()
      if (c === ',') {
        this.i++
        continue
      }
      if (c === ']') {
        this.i++
        return newArray(items)
      }
      this.fail('trailing text after a value')
    }
  }

  inlineTable(path) {
    this.i++
    const table = newTable(false)
    this.skipSpace()
    if (this.atEnd()) this.fail('unterminated inline table')
    if (this.peek() === '}') {
      this.i++
      return table
    }
    for (;;) {
      this.skipSpace()
      if (this.atEnd()) this.fail('unterminated inline table')
      const keys = this.dottedName()
      this.skipSpace()
      if (this.peek() !== '=') this.fail('expected = in an inline table')
      this.i++
      const spot = this.walk(table, keys, path)
      const value = this.value(spot.path)
      if (spot.table.map.has(spot.key)) this.fail(`key ${spot.path} is defined twice`)
      spot.table.map.set(spot.key, value)
      this.skipSpace()
      if (this.atEnd()) this.fail('unterminated inline table')
      const c = this.peek()
      if (c === ',') {
        this.i++
        continue
      }
      if (c === '}') {
        this.i++
        return table
      }
      this.fail('trailing text after a value')
    }
  }

  /**
   * Walks the leading names of a dotted key, creating the tables on the way,
   * and hands back the table and key the last name lands on.
   */
  walk(table, keys, basePath) {
    let current = table
    let path = basePath
    for (let k = 0; k < keys.length - 1; k++) {
      path = joinKey(path, keys[k])
      let next = current.map.get(keys[k])
      if (next === undefined) {
        next = newTable(false)
        current.map.set(keys[k], next)
      }
      if (next.type === 'table') {
        current = next
      } else if (next.type === 'arraytable') {
        const last = next.items.length - 1
        if (last < 0) this.fail(`${path} is not a table`)
        path = joinIndex(path, last)
        current = next.items[last]
      } else {
        this.fail(`${path} is not a table`)
      }
    }
    const key = keys[keys.length - 1]
    return { table: current, key, path: joinKey(path, key) }
  }

  /** Nothing but spaces, tabs and a comment may follow a finished directive. */
  endOfLine(reason) {
    this.skipSpace()
    if (!this.atEnd()) this.fail(reason)
  }
}

class Document {
  constructor() {
    this.root = newTable(true)
    this.current = this.root
    this.path = ''
  }

  header(parser, keys, isArray) {
    let current = this.root
    let path = ''
    for (let k = 0; k < keys.length - 1; k++) {
      path = joinKey(path, keys[k])
      let next = current.map.get(keys[k])
      if (next === undefined) {
        next = newTable(false)
        current.map.set(keys[k], next)
      }
      if (next.type === 'table') {
        current = next
      } else if (next.type === 'arraytable') {
        const last = next.items.length - 1
        if (last < 0) parser.fail(`${path} is not a table`)
        path = joinIndex(path, last)
        current = next.items[last]
      } else {
        parser.fail(`${path} is not a table`)
      }
    }
    const name = keys[keys.length - 1]
    const full = joinKey(path, name)
    let held = current.map.get(name)
    if (isArray) {
      if (held === undefined) {
        held = newArrayTable()
        current.map.set(name, held)
      }
      if (held.type !== 'arraytable') parser.fail(`${full} is not an array of tables`)
      const fresh = newTable(true)
      held.items.push(fresh)
      this.current = fresh
      this.path = joinIndex(full, held.items.length - 1)
      return
    }
    if (held === undefined) {
      held = newTable(true)
      current.map.set(name, held)
    } else if (held.type !== 'table') {
      parser.fail(`${full} is not a table`)
    } else if (held.explicit) {
      parser.fail(`table ${full} is defined twice`)
    } else {
      held.explicit = true
    }
    this.current = held
    this.path = full
  }
}

/** Parses the whole document and hands back its root table. */
export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  const doc = new Document()
  for (let n = 0; n < lines.length; n++) {
    const parser = new LineParser(lines[n], n + 1)
    parser.skipSpace()
    if (parser.atEnd()) continue
    if (parser.peek() === '[') {
      const isArray = parser.s.startsWith('[[', parser.i)
      parser.i += isArray ? 2 : 1
      const keys = parser.dottedName()
      parser.skipSpace()
      const close = isArray ? ']]' : ']'
      if (!parser.s.startsWith(close, parser.i)) parser.fail('unterminated table header')
      parser.i += close.length
      parser.endOfLine('trailing text after a table header')
      doc.header(parser, keys, isArray)
      continue
    }
    const keys = parser.dottedName()
    parser.skipSpace()
    if (parser.peek() !== '=') parser.fail('expected key = value')
    parser.i++
    const spot = parser.walk(doc.current, keys, doc.path)
    const value = parser.value(spot.path)
    parser.endOfLine('trailing text after a value')
    if (spot.table.map.has(spot.key)) parser.fail(`key ${spot.path} is defined twice`)
    spot.table.map.set(spot.key, value)
  }
  return doc.root
}
"}

