#!/usr/bin/env node
/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */

import { readFileSync } from 'node:fs'
import { ParseError } from './errors.js'
import { parseDocument } from './parse.js'
import { toJson, toKeys } from './print.js'

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function main(argv) {
  if (argv.length !== 1 || (argv[0] !== 'json' && argv[0] !== 'keys')) {
    process.stderr.write('error: usage: cli.js json|keys\n')
    return 2
  }
  let out
  try {
    const root = parseDocument(readStdin())
    out = argv[0] === 'json' ? toJson(root) : toKeys(root)
  } catch (error) {
    if (!(error instanceof ParseError)) throw error
    process.stderr.write(`${error.message}\n`)
    return 2
  }
  process.stdout.write(out)
  return 0
}

process.exitCode = main(process.argv.slice(2))

